package org.jfree.chart.block;

import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.block.Block.Position;
import org.jfree.chart.block.RectangleConstraint;
import org.jfree.chart.geom.Dimension2D;
import org.jfree.chart.geom.Size2D;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.Size2D;
import org.jfree.data.
import org.junit.Before;
import org.jfree.data.Range;
import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BorderArrangement.arrangeFF.
 * Since arrangeFF is protected, we use a test subclass to expose it.
 */
public class BorderArrangement_arrangeFF_TriageGen0Test {

    private TestableBorderArrangement arrangement;
    private BlockContainer mockContainer;
    private Graphics2D mockG2;

    // Subclass to access protected method
    private static class TestableBorderArrangement extends BorderArrangement {
        public Block topBlock;
        public Block bottomBlock;
        public Block leftBlock;
        public Block rightBlock;
        public Block centerBlock;

        // We need to override add or use reflection to set these fields if they are private.
        // Based on the provided code, the method accesses 'this.topBlock' etc directly.
        // In JFreeChart, these are usually managed via add(Block, Object).
        // However, to test the logic of arrangeFF directly as requested, we simulate the internal state.

        @Override
        public void add(Block block, Object key) {
            super.add(block, key);
            if (key == Position.TOP) {
                this.topBlock = block;
            } else if (key == Position.BOTTOM) {
                this.bottomBlock = block;
            } else if (key == Position.LEFT) {
                this.leftBlock = block;
            } else if (key == Position.RIGHT) {
                this.rightBlock = block;
            } else if (key == Position.CENTER) {
                this.centerBlock = block;
            }
        }

        // Helper to inject mocks directly since the fields are likely private in the real class
        public void setBlocks(Block top, Block bottom, Block left, Block right, Block center) {
            this.topBlock = top;
            this.bottomBlock = bottom;
            this.leftBlock = left;
            this.rightBlock = right;
            this.centerBlock = center;
        }

        @Override
        public Size2D arrange(BlockContainer container, Graphics2D g2, RectangleConstraint constraint) {
            return arrangeFF(container, g2, constraint);
        }
    }

    @Before
    public void setUp() {
        arrangement = new TestableBorderArrangement();
        mockContainer = mock(BlockContainer.class);
        mockG2 = mock(Graphics2D.class);
    }

    @Test
    public void testArrangeFF_AllNull() {
        RectangleConstraint constraint = new RectangleConstraint(100, 100);
        Size2D result = arrangement.arrange(mockContainer, mockG2, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(100.0, result.getHeight(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyTop() {
        Block top = mock(Block.class);
        arrangement.setBlocks(top, null, null, null, null);

        when(top.arrange(any(), any())).thenReturn(new Size2D(100, 20));

        RectangleConstraint constraint = new RectangleConstraint(100, 100);
        arrangement.arrange(mockContainer, mockG2, constraint);

        verify(top).arrange(any(), any());
        verify(top).setBounds(new Rectangle2D.Double(0.0, 0.0, 100.0, 20.0));
    }

    @Test
    public void testArrangeFF_AllBlocks() {
        Block top = mock(Block.class);
        Block bottom = mock(Block.class);
        Block left = mock(Block.class);
        Block right = mock(Block.class);
        Block center = mock(Block.class);
        arrangement.setBlocks(top, bottom, left, right, center);

        // Setup sizes
        // top: w=100, h=20
        when(top.arrange(any(), any())).thenReturn(new Size2D(100, 20));
        // bottom: w=100, h=30
        when(bottom.arrange(any(), any())).thenReturn(new Size2D(100, 30));
        // left: w=10, h=50 (100 - 20 - 30 = 50)
        when(left.arrange(any(), any())).thenReturn(new Size2D(10, 50));
        // right: w=15, h=50 (100 - 10 - centerW)
        // Note: w[4] = constraint.getWidth() - w[3] - w[2]. 
        // In code: w[3] is right width.
        when(right.arrange(any(), any())).thenReturn(new Size2D(15, 50));
        // center: w=75 (100 - 15 - 10), h=50
        when(center.arrange(any(), any())).thenReturn(new Size2D(75, 50));

        RectangleConstraint constraint = new RectangleConstraint(100, 100);
        Size2D result = arrangement.arrange(mockContainer, mockG2, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(100.0, result.getHeight(), 0.001);

        // Verify bounds logic
        // top: (0, 0, 100, 20)
        verify(top).setBounds(new Rectangle2D.Double(0.0, 0.0, 100.0, 20.0));
        // bottom: (0, h[0]+h[2], w[1], h[1]) -> (0, 20+50, 100, 30) = (0, 70, 100, 30)
        verify(bottom).setBounds(new Rectangle2D.Double(0.0, 70.0, 100.0, 30.0));
        // left: (0, h[0], w[2], h[2]) -> (0, 20, 10, 50)
        verify(left).setBounds(new Rectangle2D.Double(0.0, 20.0, 10.0, 50.0));
        // right: (w[2]+w[4], h[0], w[3], h[3]) 
        // w[4] = 100 - 15 - 10 = 75. 
        // right x = 10 + 75 = 85.
        // right: (85, 20, 15, 50)
        verify(right).setBounds(new Rectangle2D.Double(85.0, 20.0, 15.0, 50.0));
        // center: (w[2], h[0], w[4], h[4]) -> (10, 20, 75, 50)
        verify(center).setBounds(new Rectangle2D.Double(10.0, 20.0, 75.0, 50.0));
    }

    @Test
    public void testArrangeFF_PartialBlocks() {
        Block left = mock(Block.class);
        Block right = mock(Block.class);
        arrangement.setBlocks(null, null, left, right, null);

        // h[0]=0, h[1]=0, h[2]=100
        when(left.arrange(any(), any())).thenReturn(new Size2D(20, 100));
        when(right.arrange(any(), any())).thenReturn(new Size2D(30, 100));

        RectangleConstraint constraint = new RectangleConstraint(100, 100);
        arrangement.arrange(mockContainer, mockG2, constraint);

        // w[2]=20, w[3]=30, w[4]=100-30-20=50
        // left: (0, 0, 20, 100)
        verify(left).setBounds(new Rectangle2D.Double(0.0, 0.0, 20.0, 100.0));
        // right: (20+50, 0, 30, 100) = (70, 0, 30, 100)
        verify(right).setBounds(new Rectangle2D.Double(70.0, 0.0, 30.0, 100.0));
    }

    @Test
    public void testArrangeFF_OnlyCenter() {
        Block center = mock(Block.class);
        arrangement.setBlocks(null, null, null, null, center);

        RectangleConstraint constraint = new RectangleConstraint(100, 100);
        arrangement.arrange(mockContainer, mockG2, constraint);

        // w[2]=0, w[3]=0, w[4]=100
        // center: (0, 0, 100, 100)
        verify(center).arrange(any(), any());
        verify(center).setBounds(new Rectangle2D.Double(0.0, 0.0, 100.0, 100.0));
    }
}
